update user_back_asset
set balance        = balance + #{changeBalance},
    frozen_balance = frozen_balance + #{changeFrozenBalance}
where address = #{address}
  and coin_type = #{coinType}
  and balance + #{changeBalance} >= 0
  and frozen_balance + #{changeFrozenBalance} >= 0

